import React, { useState } from 'react';
import ContentList from '../components/ContentList';
import ContentForm from '../components/ContentForm';

// Mock threads
const threads = [
  { id: 1, title: 'Ring 0: kernel exploit discussion', posts: [ {id:1, author: 'neo', body: 'Alguien probó el exploit CVE-XXXX?' } ] },
  { id: 2, title: 'Best terminal themes 2025', posts: [ {id:2, author: 'trinity', body: 'Mi favorito es gruvbox + powerline' } ] }
];

const ContentPage = ({ match }) => {
  const [activeThreadId, setActiveThreadId] = useState(threads[0].id);
  const thread = threads.find(t => t.id === activeThreadId) || threads[0];

  return (
    <main className="container">
      <div className="row">
        <div className="col">
          <h2 className="neon">Hilos</h2>
          <ContentList onSelect={(id) => setActiveThreadId(id)} selectedId={activeThreadId} />
        </div>
        <div className="col">
          <div className="card">
            <h3>{thread.title}</h3>
            <div>
              {thread.posts.map(p => (
                <article key={p.id} className="card" style={{ marginBottom: '0.5rem' }}>
                  <div style={{ fontSize: '0.85rem', color: '#9bd6b1' }}>{p.author}</div>
                  <p style={{ marginTop: '0.25rem' }}>{p.body}</p>
                </article>
              ))}
            </div>

            <h4>Responder</h4>
            <ContentForm threadId={thread.id} />
          </div>
        </div>
      </div>
    </main>
  );
};

export default ContentPage;
